def transform(A):
    """Performs one transformation step on the list A."""
    new_A = []
    for i in range(len(A)):
        new_A.append(A[i])
        if i < len(A) - 1:
            new_A.append(A[i] + A[i+1])
    return new_A

# Simulate L=3, K up to 5, initial numbers 1, 2, 3
A = [1, 2, 3]
K_steps = 5
results = {}

for k in range(K_steps):
    A = transform(A)
    # Record the count of 1, 2, 3 for K=k+1
    results[k+1] = {
        'length': len(A),
        'count_1': A.count(1),
        'count_2': A.count(2),
        'count_3': A.count(3)
    }

print("--- Simulation Results (L=3) ---")
for k, data in results.items():
    print(f"K={k}: Length={data['length']}, Count_1={data['count_1']}, Count_2={data['count_2']}, Count_3={data['count_3']}")
